[Form]
public class AVATonnageCalcedData extends FormRun
{
    KCS_TonnageSetup    frmKCS_TonnageSetup;

    InventSiteId    frmInventSiteId;
    StartDate       frmStartDate;
    EndDate         frmEndDate;

    Query                   frmQueryKCS_TonnageCalcedData;
    QueryBuildDataSource    frmQbdsTransDate;
    QueryBuildRange         frmQbrTransDate;


}

/// <summary>
///    AVA <c>init</c> method.
/// </summary>
public void init()
{
    frmKCS_TonnageSetup = KCS_TonnageSetup::find();

    super();

    this.initQuery();
}

/// <summary>
///    AVA <c>initQuery</c> method.
/// </summary>
public void initQuery()
{
    //frmQbdsTransDate    = KCS_TonnageCalcedData_DS.query().dataSourceTable( tableNum(KCS_TonnageCalcedData));
    //frmQbrTransDate     = frmQbdsTransDate.addRange(fieldNum(KCS_TonnageCalcedData, TransDate));

    frmStartDate    = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
    frmEndDate      = frmStartDate + frmKCS_TonnageSetup.Days;

    KCS_TonnageCalcedData_StartDate.dateValue(frmStartDate);
    KCS_TonnageCalcedData_EndDate.dateValue(frmEndDate);

    this.modifyQueryDateRange(true);
}

/// <summary>
///    AVA <c>modifyQueryRange</c> method.
/// </summary>
public void modifyQueryDateRange(boolean _initMode = false)
{
    //frmQbrTransDate = SysQuery::findOrCreateRange(KCS_TonnageCalcedData_DS.queryBuildDataSource(), fieldNum(KCS_TonnageCalcedData, TransDate));

    if (frmStartDate && frmEndDate)
    {
        //frmQbrTransDate.value(SysQuery::range(frmStartDate, frmEndDate));
        SysQuery::findOrCreateRange(KCS_TonnageCalcedData_DS.queryBuildDataSource(), fieldNum(KCS_TonnageCalcedData, TransDate)).value(SysQuery::range(frmStartDate, frmEndDate));
    }
    else if (frmStartDate)
    {
        //frmQbrTransDate.value(SysQuery::range(frmStartDate, DateTimeUtil::maxValue()));
        SysQuery::findOrCreateRange(KCS_TonnageCalcedData_DS.queryBuildDataSource(), fieldNum(KCS_TonnageCalcedData, TransDate)).value(SysQuery::range(frmStartDate, DateTimeUtil::maxValue()));
    }
    else if (frmEndDate)
    {
        //frmQbrTransDate.value(SysQuery::range(DateTimeUtil::minValue(), frmEndDate));
        SysQuery::findOrCreateRange(KCS_TonnageCalcedData_DS.queryBuildDataSource(), fieldNum(KCS_TonnageCalcedData, TransDate)).value(SysQuery::range(DateTimeUtil::minValue(), frmEndDate));
    }
    else
    {
        //frmQbrTransDate.value(SysQuery::valueUnlimited());
        SysQuery::findOrCreateRange(KCS_TonnageCalcedData_DS.queryBuildDataSource(), fieldNum(KCS_TonnageCalcedData, TransDate)).value(SysQuery::valueUnlimited());
    }

    //SysQuery::findOrCreateRange(KCS_TonnageCalcedData_DS.queryBuildDataSource(), fieldNum(KCS_TonnageCalcedData, TransDate)).value(queryValue(frmQbrTransDate));
    if(!_initMode)
    {
        KCS_TonnageCalcedData_DS.executeQuery();
    }
}

/// <summary>
///    AVA <c>calculateTonnageData</c> method.
/// </summary>
public void calculateTonnageData()
{
    Args                locArgs;
    AVATonnageContract  locAVATonnageContract;
    AVATonnageExecution locAVATonnageExecution;

    locArgs = new Args();
    locArgs.caller(this);

    locAVATonnageContract = new AVATonnageContract();

    locAVATonnageContract.parmArgs(locArgs);
    locAVATonnageContract.parmAutomaticMode(false);
    locAVATonnageContract.parmEndDate(KCS_TonnageCalcedData_EndDate.dateValue());
    locAVATonnageContract.parmInventSiteId(KCS_TonnageCalcedData_InventSiteId.valueStr());
    locAVATonnageContract.parmStartDate(KCS_TonnageCalcedData_StartDate.dateValue());
    locAVATonnageContract.parmTonnageDaysForwardCalculation(frmKCS_TonnageSetup.Days);
    locAVATonnageContract.parmTonnagePercentageWarning(frmKCS_TonnageSetup.PercentWarning);

    locAVATonnageExecution = AVATonnageExecution::newFromArgs(locAVATonnageContract.parmArgs());
    locAVATonnageExecution.parmDataContract(locAVATonnageContract);
    locAVATonnageExecution.init();

    locAVATonnageExecution.calcTonnageFromParams();
}

/// <summary>
///    AVA <c>clicked</c> method.
/// </summary>
public void clicked()
{
    super();

    element.calculateTonnageData();

    KCS_TonnageCalcedData_DS.research();
}

/// <summary>
///    AVA <c>modified</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean modified()
{
    boolean         retVal;

    InventSiteId    qValue;

    retVal = super();

    qValue = this.valueStr();

    if (qValue)
    {
        SysQuery::findOrCreateRange(KCS_TonnageCalcedData_DS.queryBuildDataSource(), fieldNum(KCS_TonnageCalcedData, InventSiteId)).value(queryValue(qValue));
    }
    else
    {
        SysQuery::findOrCreateRange(KCS_TonnageCalcedData_DS.queryBuildDataSource(), fieldNum(KCS_TonnageCalcedData, InventSiteId)).value(SysQueryRangeUtil::valueUnlimited());
    }

    KCS_TonnageCalcedData_DS.executeQuery();

    return retVal;
}

