/// <summary>
///    AVA <c>modified</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean modified()
{
    boolean retVal;

    retVal = super();

    frmEndDate      = this.dateValue();

    element.modifyQueryDateRange();

    return retVal;
}
